:root {
  --bg: #faf6f1;
  --surface: #ffffff;
  --surface-2: #fdf9f4;
  --ink: #1c1a17;
  --ink-soft: #5a544c;
  --ink-mute: #8b8378;
  --line: #ece5db;
  --line-strong: #ddd3c5;
  --accent: #c2502e;
  --accent-dark: #9e3c20;
  --accent-soft: #fbe9e2;
  --green: #2f8f5b;
  --green-soft: #e0f1e8;
  --amber: #d98a2b;
  --amber-soft: #fdeed6;
  --red: #d1402e;
  --red-soft: #fbe0db;
  --blue: #2f6db5;
  --blue-soft: #dde9f7;
  --shadow: 0 6px 24px rgba(58, 38, 25, 0.08);
  --shadow-lg: 0 14px 44px rgba(58, 38, 25, 0.14);
  --radius: 16px;
  --radius-sm: 10px;
  --font-display: 'Fraunces', serif;
  --font-body: 'Manrope', system-ui, sans-serif;
}

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  font-family: var(--font-body);
  color: var(--ink);
  background:
    radial-gradient(1200px 600px at 85% -10%, #f3e6d8 0%, transparent 60%),
    radial-gradient(900px 500px at -10% 110%, #f1e3d3 0%, transparent 55%),
    var(--bg);
  -webkit-font-smoothing: antialiased;
}

#app { min-height: 100%; }
.screen { display: none; }
.screen.active { display: block; }

/* ============ SPLASH ============ */
.splash {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  padding: 24px;
}
.splash-brand { display: flex; align-items: center; gap: 12px; font-family: var(--font-display); font-size: 1.6rem; font-weight: 700; }
.splash-status { color: var(--ink-mute); font-size: 0.95rem; letter-spacing: 0.01em; }

/* logo */
.logo-dot {
  width: 16px; height: 16px; border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--accent-soft);
  display: inline-block;
}

/* ============ AUTH ============ */
.screen-auth.active {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  min-height: 100vh;
}
.auth-illustration {
  position: relative;
  background: linear-gradient(135deg, #e9d8c6 0%, #f4e8db 100%);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.auth-illustration::before {
  content: '';
  position: absolute; inset: 0;
  background:
    radial-gradient(300px 300px at 30% 40%, rgba(194, 80, 46, 0.18), transparent 70%),
    radial-gradient(260px 260px at 70% 65%, rgba(217, 138, 43, 0.18), transparent 70%);
}
.plate {
  position: relative;
  width: min(56vw, 320px);
  height: min(56vw, 320px);
  display: grid;
  place-items: center;
  animation: bob 6s ease-in-out infinite;
}
.plate-ring {
  position: absolute; inset: 8%;
  border-radius: 50%;
  border: 2px dashed rgba(158, 60, 32, 0.35);
  animation: spin 40s linear infinite;
}
.plate-glow {
  position: absolute; inset: 18%;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, #fff, #f3e6d8);
  box-shadow: var(--shadow-lg);
}
.plate-emoji {
  position: relative;
  font-size: min(22vw, 120px);
  line-height: 1;
}
.side-notes {
  position: absolute;
  right: 6%;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.note-chip {
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(6px);
  border: 1px solid rgba(255, 255, 255, 0.6);
  border-radius: 999px;
  padding: 10px 16px;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--ink);
  box-shadow: var(--shadow);
  display: flex;
  gap: 10px;
  justify-content: space-between;
  animation: bob 6s ease-in-out infinite;
}
.note-chip:nth-child(2) { animation-delay: 0.6s; }
.note-chip:nth-child(3) { animation-delay: 1.2s; }
.note-chip b { color: var(--accent); }

.auth-panel {
  padding: 48px 8vw;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.auth-brand { display: flex; align-items: center; gap: 10px; font-family: var(--font-display); font-weight: 700; font-size: 1.25rem; }
.auth-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  margin: 28px 0 10px;
  letter-spacing: -0.02em;
  line-height: 1.05;
}
.auth-sub { color: var(--ink-soft); margin: 0 0 28px; max-width: 46ch; }

.auth-tabs {
  display: inline-flex;
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 4px;
  margin-bottom: 22px;
  width: fit-content;
}
.tab {
  border: none;
  background: transparent;
  padding: 9px 20px;
  border-radius: 999px;
  font-family: inherit;
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--ink-mute);
  cursor: pointer;
  transition: all 0.2s;
}
.tab.active { background: var(--ink); color: #fff; }

.auth-form { display: flex; flex-direction: column; gap: 14px; }
.field { display: flex; flex-direction: column; gap: 6px; }
.field span { font-size: 0.8rem; font-weight: 600; color: var(--ink-soft); }
.field input {
  font-family: inherit;
  font-size: 1rem;
  padding: 12px 14px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--ink);
  transition: border-color 0.15s, box-shadow 0.15s;
}
.field input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 4px var(--accent-soft);
}

.auth-hint {
  margin-top: 26px;
  padding: 14px 16px;
  background: var(--surface-2);
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius-sm);
  font-size: 0.8rem;
  color: var(--ink-soft);
  line-height: 1.7;
}
.auth-hint code {
  background: #fff;
  padding: 1px 6px;
  border-radius: 4px;
  border: 1px solid var(--line);
  font-size: 0.75rem;
}

/* ============ BOTÕES ============ */
.btn {
  font-family: inherit;
  font-weight: 700;
  border: none;
  cursor: pointer;
  border-radius: 12px;
  padding: 11px 20px;
  font-size: 0.95rem;
  transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.15s;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--accent); color: #fff; box-shadow: 0 8px 20px rgba(194, 80, 46, 0.32); }
.btn-primary:hover { background: var(--accent-dark); }
.btn-ghost { background: transparent; color: var(--ink-soft); border: 1px solid var(--line-strong); }
.btn-ghost:hover { background: var(--surface-2); }
.btn-danger { background: var(--red); color: #fff; }
.btn-danger:hover { background: #b0301f; }
.btn-lg { padding: 14px 26px; font-size: 1rem; }
.btn-sm { padding: 7px 14px; font-size: 0.85rem; }

.form-error { color: var(--red); font-size: 0.88rem; min-height: 1.1em; font-weight: 600; }

/* ============ TOPBAR ============ */
.topbar {
  position: sticky;
  top: 0;
  z-index: 20;
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--line);
  padding: 14px 5vw;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.topbar-brand { display: flex; align-items: center; gap: 10px; font-family: var(--font-display); font-weight: 800; font-size: 1.2rem; }
.topbar-nav { display: flex; gap: 6px; }
.nav-link {
  background: transparent;
  border: none;
  font-family: inherit;
  font-weight: 600;
  font-size: 0.92rem;
  color: var(--ink-soft);
  padding: 9px 18px;
  border-radius: 999px;
  cursor: pointer;
  transition: all 0.18s;
  position: relative;
}
.nav-link:hover { background: var(--surface-2); color: var(--ink); }
.nav-link.active { color: var(--accent); background: var(--accent-soft); }
.nav-badge {
  background: var(--accent);
  color: #fff;
  font-size: 0.7rem;
  border-radius: 999px;
  padding: 2px 7px;
  margin-left: 6px;
  font-weight: 700;
}

.topbar-right { display: flex; align-items: center; gap: 12px; }
.user-chip { display: flex; align-items: center; gap: 10px; }
.avatar {
  width: 40px; height: 40px;
  border-radius: 50%;
  background: var(--ink);
  color: #fff;
  display: grid;
  place-items: center;
  font-weight: 800;
  font-size: 0.95rem;
}
.user-info { display: flex; flex-direction: column; line-height: 1.2; }
.user-name { font-weight: 700; font-size: 0.92rem; }
.user-role { font-size: 0.75rem; color: var(--ink-mute); text-transform: capitalize; }

/* ============ CONTENT ============ */
.content { padding: 36px 5vw 80px; max-width: 1240px; margin: 0 auto; }

.section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 26px;
  gap: 16px;
  flex-wrap: wrap;
}
.section-head h2 {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  font-weight: 800;
  margin: 0;
  letter-spacing: -0.02em;
}
.section-head p { margin: 6px 0 0; color: var(--ink-soft); }

/* ============ CARDÁPIO ============ */
.menu-controls { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.search-input {
  padding: 10px 14px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  font-family: inherit;
  font-size: 0.9rem;
  background: var(--surface);
