.dish-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); border-color: var(--line-strong); }
.dish-card.out { opacity: 0.6; }
.dish-tag {
  font-size: 0.72rem;
  font-weight: 700;
