}
.dish-desc { color: var(--ink-soft); font-size: 0.9rem; flex: 1; line-height: 1.5; }
.dish-foot { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-top: 4px; }
.dish-price { font-weight: 800; font-size: 1.1rem; color: var(--ink); }
.dish-badge {
  font-size: 0.7rem;
