}
.dish-add:hover { background: var(--accent-dark); transform: scale(1.03); }
.dish-add:disabled { background: var(--line-strong); cursor: not-allowed; transform: none; }

.qty-stepper { display: inline-flex; align-items: center; gap: 8px; background: var(--surface-2); border-radius: 999px; padding: 3px; }
.qty-stepper button {
