/* ============ PEDIDOS / TABELA ============ */
.filter-row { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 22px; }
.stat-row { display: flex; gap: 14px; flex-wrap: wrap; margin-bottom: 26px; }
.stat-card {
  flex: 1;
  min-width: 150px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 18px 20px;
  box-shadow: var(--shadow);
}
.stat-label { font-size: 0.78rem; color: var(--ink-mute); text-transform: uppercase; letter-spacing: 0.06em; font-weight: 700; }
.stat-value { font-family: var(--font-display); font-size: 2rem; font-weight: 800; margin-top: 6px; }
.stat-sub { font-size: 0.8rem; color: var(--ink-soft); margin-top: 2px; }

.order-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 20px;
  margin-bottom: 16px;
  box-shadow: var(--shadow);
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 20px;
  transition: transform 0.18s, box-shadow 0.18s;
}
.order-card:hover { box-shadow: var(--shadow-lg); }
.order-main { display: flex; flex-direction: column; gap: 12px; }
.order-top { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.order-id { font-weight: 800; font-family: var(--font-display); font-size: 1.15rem; }
.order-items { display: flex; flex-direction: column; gap: 8px; }
.order-line { display: flex; justify-content: space-between; gap: 12px; font-size: 0.92rem; color: var(--ink-soft); }
.order-line b { color: var(--ink); font-weight: 700; }
.order-note {
  background: var(--amber-soft);
  border-left: 3px solid var(--amber);
  padding: 8px 12px;
  border-radius: 6px;
  font-size: 0.85rem;
  color: var(--ink-soft);
}
.order-side { display: flex; flex-direction: column; align-items: flex-end; justify-content: space-between; gap: 12px; }
.order-total { font-family: var(--font-display); font-size: 1.4rem; font-weight: 800; }
.order-meta { font-size: 0.78rem; color: var(--ink-mute); text-align: right; line-height: 1.4; }

.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px;
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 700;
}
.badge .dot { width: 7px; height: 7px; border-radius: 50%; }
.badge.novo { background: var(--blue-soft); color: var(--blue); }
.badge.novo .dot { background: var(--blue); animation: pulse 1.6s infinite; }
.badge.preparando { background: var(--amber-soft); color: var(--amber); }
.badge.preparando .dot { background: var(--amber); animation: pulse 1.6s infinite; }
.badge.pronto { background: var(--green-soft); color: var(--green); }
.badge.pronto .dot { background: var(--green); }
.badge.entregue { background: var(--green-soft); color: var(--ink-mute); }
.badge.entregue .dot { background: var(--ink-mute); }
.badge.cancelado { background: var(--red-soft); color: var(--red); }
.badge.cancelado .dot { background: var(--red); }

.sit-actions { display: flex; gap: 8px; flex-wrap: wrap; justify-content: flex-end; }
.sit-btn {
  border: 1px solid var(--line-strong);
  background: #fff;
  padding: 7px 13px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.82rem;
  cursor: pointer;
  font-family: inherit;
  color: var(--ink-soft);
  transition: all 0.15s;
}
.sit-btn:hover:not(:disabled) { border-color: var(--accent); color: var(--accent); }
.sit-btn.active { background: var(--ink); color: #fff; border-color: var(--ink); }
.sit-btn:disabled { opacity: 0.45; cursor: not-allowed; }

.empty-state {
