  color: var(--ink-mute);
}
.empty-state .emoji { font-size: 3rem; margin-bottom: 12px; }
.empty-state h3 { font-family: var(--font-display); font-size: 1.4rem; color: var(--ink); margin: 0 0 8px; }

/* ============ GERENTE: FORM PRATO ============ */
.dish-form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 14px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 20px;
  margin-bottom: 24px;
  box-shadow: var(--shadow);
  align-items: end;
}
.dish-form-actions { display: flex; gap: 10px; align-items: end; }

.dish-table {
  width: 100%;
  border-collapse: collapse;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
}
.dish-table th {
  text-align: left;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ink-mute);
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--surface-2);
  font-weight: 700;
}
.dish-table td { padding: 14px 16px; border-bottom: 1px solid var(--line); font-size: 0.92rem; vertical-align: middle; }
.dish-table tr:last-child td { border-bottom: none; }
.dish-table tr:hover td { background: var(--surface-2); }
.dish-table .name-cell { font-weight: 700; }
.table-actions { display: flex; gap: 8px; }
.icon-btn {
  width: 34px; height: 34px;
  border-radius: 8px;
  border: 1px solid var(--line-strong);
  background: #fff;
  cursor: pointer;
  font-size: 0.9rem;
  transition: all 0.15s;
}
.icon-btn:hover { border-color: var(--accent); background: var(--accent-soft); }
.icon-btn.danger:hover { border-color: var(--red); background: var(--red-soft); }
.switch { display: inline-flex; align-items: center; gap: 8px; cursor: pointer; user-select: none; }
.switch input { accent-color: var(--green); width: 16px; height: 16px; }

/* ============ MODAL ============ */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(28, 26, 23, 0.55);
  backdrop-filter: blur(4px);
  display: grid;
  place-items: center;
  z-index: 50;
  padding: 20px;
  animation: fade 0.2s;
}
.modal-backdrop[hidden] { display: none; }
.modal {
  background: var(--surface);
  border-radius: 20px;
  width: 100%;
  max-width: 520px;
  max-height: 90vh;
  overflow: auto;
  box-shadow: var(--shadow-lg);
  animation: pop 0.25s;
}
.modal-head {
  padding: 22px 26px 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.modal-head h3 { font-family: var(--font-display); font-size: 1.5rem; margin: 0; font-weight: 800; }
.modal-body { padding: 8px 26px 16px; display: flex; flex-direction: column; gap: 14px; }
.modal-foot { padding: 12px 26px 24px; display: flex; justify-content: flex-end; gap: 10px; }
.close-x {
  background: none;
  border: none;
  font-size: 1.4rem;
  cursor: pointer;
  color: var(--ink-mute);
  line-height: 1;
}

.cart-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px dashed var(--line);
}
.cart-item:last-child { border-bottom: none; }
.cart-item-name { font-weight: 700; flex: 1; }
.cart-item-price { color: var(--ink-soft); font-size: 0.88rem; }
.total-row {
  display: flex;
  justify-content: space-between;
  padding-top: 14px;
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 800;
}

/* ============ TOAST ============ */
.toast-wrap {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  gap: 10px;
  z-index: 60;
  align-items: center;
}
.toast {
  background: var(--ink);
  color: #fff;
  padding: 12px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.9rem;
  box-shadow: var(--shadow-lg);
  animation: rise 0.3s;
  display: flex;
  align-items: center;
  gap: 10px;
}
.toast.success { background: var(--green); }
.toast.error { background: var(--red); }
.toast.leaving { animation: fall 0.3s forwards; }

/* ============ ANIMAÇÕES ============ */
@keyframes spin { to { transform: rotate(360deg); } }
@keyframes bob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-14px); } }
@keyframes pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.4; transform: scale(0.7); } }
@keyframes fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes pop { from { opacity: 0; transform: scale(0.94); } to { opacity: 1; transform: scale(1); } }
@keyframes rise { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }
@keyframes fall { to { opacity: 0; transform: translateY(12px); } }

/* stagger reveal */
.reveal { animation: rise 0.5s both; }

/* ============ RESPONSIVO ============ */
@media (max-width: 820px) {
  .screen-auth.active { grid-template-columns: 1fr; }
  .auth-illustration { display: none; }
  .auth-panel { padding: 32px 24px; justify-content: flex-start; }
  .topbar { flex-wrap: wrap; padding: 12px 4vw; }
  .topbar-nav { order: 3; width: 100%; margin-top: 8px; overflow-x: auto; }
  .content { padding: 24px 4vw 90px; }
  .order-card { grid-template-columns: 1fr; }
  .order-side { align-items: flex-start; }
  .order-meta { text-align: left; }
  .sit-actions { justify-content: flex-start; }
  .cart-fab { right: 16px; bottom: 16px; padding: 13px 20px; }
}

